using Microsoft.AspNetCore.Mvc;using RaceDay.Mvc.Services;namespace RaceDay.Mvc.Controllers;public class HomeController(RaceApi api):Controller{public async Task<IActionResult> Index(string? q,string? type,string? city){var events=await api.Get<List<RaceEvent>>("api/events")??new();if(!string.IsNullOrWhiteSpace(q))events=events.Where(e=>e.EventName.Contains(q,StringComparison.OrdinalIgnoreCase)||(e.Description?.Contains(q,StringComparison.OrdinalIgnoreCase)??false)).ToList();if(!string.IsNullOrWhiteSpace(type))events=events.Where(e=>e.EventType.Equals(type,StringComparison.OrdinalIgnoreCase)).ToList();if(!string.IsNullOrWhiteSpace(city))events=events.Where(e=>e.City.Contains(city,StringComparison.OrdinalIgnoreCase)).ToList();ViewBag.Query=q;ViewBag.Type=type;ViewBag.City=city;return View(events);}public async Task<IActionResult> Details(int id){var e=await api.Get<EventDetails>("api/events/"+id);return e==null?NotFound():View(e);} [HttpPost,ValidateAntiForgeryToken]public async Task<IActionResult> Enter(int id,int categoryId,string? emergencyContactName,string? emergencyContactPhone){if(HttpContext.Session.GetString("role")!="Participant")return RedirectToAction("Login","Account");var r=await api.Send(HttpMethod.Post,"api/enrolments",new{categoryId,emergencyContactName,emergencyContactPhone});TempData["Notice"]=r.ok?"Entry confirmed in the system.":r.error;return RedirectToAction(nameof(Details),new{id});}public IActionResult Error()=>View();}